fn min_inspectors(n: i8, d: i8) -> i8 {
    // Each inspector covers a contiguous block of length `2*d + 1`.
    let coverage = 2 * d + 1;
    // The minimum number of inspectors is ceil(n / coverage).
    // For integers, ceil(a/b) = (a + b - 1) / b.
    (n + coverage - 1) / coverage
}

